INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1498541-mgt450', 'stk-user9840', 'MGT 450', 'info', '{"desc": "هذا الموضوع مخصص لمناقشة المقرر المذكور في العنوان\nبنود تساعد في تقييم المقرر:\n\nجودة المقرر بشكل عام\nالمواضيع التي يغطيها المقرر\nالكتاب المستخدم للمقرر\nالأسئلة والأمثلة المستخدمة في المقرر\nمدى فائدته في الناحية التطبيقية\n\nولكم الحرية في تقييم المقرر باستحداث بنود أخرى ترونها مناسبه لتقييمه.\n\nكما نرجو تحري الصدق والعدل في تقييم المقرر\nوعدم الخلط بين تقييم الأستاذ وتقييم المقرر بذاته", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-450-management-of-innovation-and-change/180029/1", "user": "user9840", "ts": 1535754972000, "tid": 180029, "pn": 1}}', 1535754972000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_182-mgt450', 'stk-_182', 'MGT 450', 'doc', '{"docs": [{"id": "stk-dr-f98461", "n": "Dr. Khaled M. Al-Zamel", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أعتقد الشباب يتكلمون عن شخص آخر.\n\nMGT450-192\n\nالتحضير: مو ثابت، قد يبدأ المحاضرة بالتحضير أو يختمها فيه\n\nطريقة الشرح: ملخص فصول الكتاب بصفحات معدودة يعرضها على الجهاز. كل فصل ملخصه في ٥-٨ صفحات فقط\n\nالكويزات: لا يوجد\n\nالمياجر والفاينلات: ٣ مياجر وفاينل، يحذف أسوأهم. الاختبارات اختيار متعدد وصح وخطأ. سهلة، يجيبها بالنص من الملخص اللي يشرحلكم منه، كل اختبار يغطي ٤-٥ ملخصات\n\nالصوت: واضح\n\nالقريد النهائي: +A\n\nإضافات :\n\nالمادة ماهي مطلوبة مني لكن نزلتها لأن هو يدرسها، مما يدل لكم على أن هذا الأستاذ ثروة\nالأستاذ موسوعة، خبرة، خلوق، حبيب وخفيف دم\nمتفهم عند الغيابات والخروج المبكر من المحاضرة. أهم شيء علمه مسبقًا وبيّن أنك مهتم\nيتكلم بالعربية غالبًا، إلا إن وُجد طالب أجنبي\nيطلب من كل طالب تلخيص كتاب (مو لازم تقراه، تكفي قراءة ملخصه -واللي بيوفره لكم- وتعرضه حسب فهمك). العرض ممكن يكو نباوربوينت -يفضله الأستاذ للوضوح-، وقد تعرض وأنت جالس بمكانك. بكل الحالتين بتاخذ الدرجة.\nأنصح بالأستاذ خالد في أي مادة، والله يحفظه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525178-mgt450", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-khaled-m-al-zamel/98461/10", "user": "_182", "ts": 1598633584000, "tid": 98461, "pn": 10}}]}', 1598633584000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
